import threading

碗 = [{n1}, {n2}, {n3}]
结果 = [0, 0, 0]


def 翻倍(序号, 数):
    结果[序号] = 数 * 2


猫们 = []
for i in range(3):
    一只猫 = threading.Thread(target=翻倍, args=(i, 碗[i]))
    猫们.append(一只猫)

for 一只猫 in 猫们:
    一只猫.start()

for 一只猫 in 猫们:
    一只猫.join()

for 一个数 in 结果:
    print(一个数)
